+func trailListPageQuery(statusFilters []trail.Status, pageSize int, pageToken string) string {
+	q := url.Values{}
+	if len(statusFilters) > 0 {
+		parts := make([]string, len(statusFilters))
+		for i, status := range statusFilters {
