+	}
+	q.Set("pageSize", strconv.Itoa(pageSize))
+	if strings.TrimSpace(pageToken) != "" {
+		q.Set("pageToken", strings.TrimSpace(pageToken))
+	}
+	return "?" + q.Encode()
